{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL injection vulnerability",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4",
      "explanation": "The Apex class constructs a SOQL query by concatenating user input directly into the query string without using bind variables. This makes it vulnerable to SOQL injection attacks where malicious input could manipulate the query to access unauthorized data.",
      "remediation": "Replace the dynamic query construction with a static SOQL query using bind variables like 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50'."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violation in OpportunityStageService",
      "severity": "High",
      "file": "OpportunityStageService.cls",
      "lines": "7",
      "explanation": "The class uses WITH USER_MODE in the SOQL query but does not enforce field-level security. The Opportunity.StageName field is editable in the permission set, but the code updates this field without checking if the user has sufficient permissions to modify it. Additionally, the Amount field is readable but not editable in the permission set, yet the code retrieves it.",
      "remediation": "Use Security.stripInaccessible() after the SOQL query to enforce field-level security and ensure only accessible fields are returned. Also, verify that the user has appropriate CRUD permissions before attempting to update the StageName field."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4",
      "explanation": "The Apex class does not enforce CRUD/FLS checks. It directly queries and updates a Contact record without verifying if the user has appropriate permissions to read or modify the Phone field. This can lead to data exposure or modification beyond user permissions.",
      "remediation": "Add WITH USER_MODE to the SOQL query and use Security.stripInaccessible() after querying to ensure that only accessible fields are returned and that CRUD/FLS are enforced."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Missing sharing enforcement",
      "severity": "High",
      "file": "CaseHistoryController.cls",
      "lines": "1",
      "explanation": "The class is declared 'without sharing', which means it ignores record-level sharing settings. This allows users to potentially access Case records they shouldn't be able to see based on their sharing rules or roles.",
      "remediation": "Change the class declaration from 'without sharing' to 'with sharing' or 'inherited sharing' to enforce proper record-level security."
    },
    {
      "category": "C2",
      "title": "Missing CRUD/FLS enforcement",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "10",
      "explanation": "While the code uses Security.stripInaccessible, it doesn't enforce CRUD/FLS at the SOQL level. This could allow users with read access to Case object but not specific fields to potentially see unauthorized field data.",
      "remediation": "Use WITH USER_MODE in SOQL queries or explicitly check field permissions using Schema.FieldPermissions before querying."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in Support Agent Tools permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "15, 16, 17, 18",
      "explanation": "The Support Agent Tools permission set grants ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled permissions. These are powerful system permissions that allow extensive data access and modification beyond what a support agent should typically need. The permission set is intended for tier-1 support agents but provides excessive privileges.",
      "remediation": "Remove the ModifyAllData, ViewAllData, AuthorApex, and ApiEnabled permissions from the Support Agent Tools permission set. Grant only the minimal required permissions such as 'Close Case' and 'Edit Case' object permissions."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C5",
      "title": "Guest user exposure via public API endpoint",
      "severity": "High",
      "file": "PublicCatalogController.cls",
      "lines": "3",
      "explanation": "The PublicCatalogController class is exposed through a @AuraEnabled method in a profile with 'Guest User License', making it callable by unauthenticated users. The method returns sensitive product data without proper field-level security enforcement, despite the profile having limited field permissions.",
      "remediation": "Remove the @AuraEnabled annotation from the method or ensure the class is not accessible to guest users. Alternatively, implement proper field-level security checks using Security.stripInaccessible() and enforce USER_MODE in all queries."
    }
  ]
}
